def build(aid: str, spec: tuple) -> dict:
    name, short, title, years, path, mission, codes, terms, funders, objs = spec
    url = path if path.startswith("http") else OSBM + path
    cite = lambda section: {"document": title, "section": section, "url": url}  # noqa: E731
    objectives = [{"id": f"{short.split()[0].upper().replace('&', '').replace('.', '')}-{gid}.{oid}" if not oid.startswith(gid)
                   else f"{short.split()[0].upper().replace('&', '').replace('.', '')}-{oid}",
                   "goal_id": gid, "goal_title": gt, "text": text, "keywords": kws,
                   "citation": cite(f"Goal {gid}, Objective {oid}")} for gid, gt, oid, text, kws in objs]
    seen = set()
    for o in objectives:  # ids must be unique within a profile
        base, n = o["id"], 2
        while o["id"] in seen:
            o["id"], n = f"{base}-{n}", n + 1
        seen.add(o["id"])
    return {
        "agency_id": aid, "name": name, "short_name": short,
        "plan": {"title": title, "years": years, "url": url, "retrieved": "2026-11-07"},
        "mission": {"text": mission, "citation": cite("Mission / purpose")},
        "responsibilities": [], "program_priorities": sorted({g for _, g, *_ in objs}),
        "operating_programs": [], "objectives": objectives, "search_terms": terms,
        "eligible_applicant_codes": codes, "preferred_funders": funders,
        "wording_note": ("Goals and objectives are close summaries of the plan posted on the OSBM Agency Strategic Plans "
                         "page (retrieved 2026-11-07); check the cited section before quoting. Keywords, search terms "
                         "and usual funders were chosen by the team as matching aids."),
        "reviewed_by": "", "profile_version": "statewide-1.0",
    }


def main():
    for aid, spec in A.items():
        p = build(aid, spec)
        (OUT / f"{aid}.json").write_text(json.dumps(p, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"wrote {len(A)} profiles to {OUT}")


if __name__ == "__main__":
    main()
